create table if not exists public.f2_products(id bigint generated by default as identity primary key,product_name text not null unique,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.f2_items(id bigint generated by default as identity primary key,product_id bigint not null references public.f2_products(id),part_no text not null,current_step integer not null default 0,attention boolean not null default false,shipped boolean not null default false,created_at timestamptz not null default now(),unique(product_id,part_no));
create table if not exists public.f2_process_logs(id bigint generated by default as identity primary key,item_id bigint not null references public.f2_items(id),machine_no integer not null check(machine_no between 1 and 5),step_no integer not null check(step_no>0),attention boolean not null default false,created_at timestamptz not null default now());
create table if not exists public.f2_tools(id bigint generated by default as identity primary key,machine_no integer not null check(machine_no between 1 and 5),t_no integer not null check(t_no between 1 and 80),tool_name text,current_machine_no integer not null check(current_machine_no between 1 and 5),attention boolean not null default false,created_at timestamptz not null default now(),unique(machine_no,t_no));
create table if not exists public.f2_tool_logs(id bigint generated by default as identity primary key,tool_id bigint not null references public.f2_tools(id),machine_no integer not null check(machine_no between 1 and 5),action text not null,target_machine_no integer check(target_machine_no between 1 and 5),created_at timestamptz not null default now());
alter table public.f2_products enable row level security;alter table public.f2_items enable row level security;alter table public.f2_process_logs enable row level security;alter table public.f2_tools enable row level security;alter table public.f2_tool_logs enable row level security;
do $$ begin create policy "f2_products_public" on public.f2_products for all using(true) with check(true); exception when duplicate_object then null; end $$;
do $$ begin create policy "f2_items_public" on public.f2_items for all using(true) with check(true); exception when duplicate_object then null; end $$;
do $$ begin create policy "f2_process_logs_public" on public.f2_process_logs for all using(true) with check(true); exception when duplicate_object then null; end $$;
do $$ begin create policy "f2_tools_public" on public.f2_tools for all using(true) with check(true); exception when duplicate_object then null; end $$;
do $$ begin create policy "f2_tool_logs_public" on public.f2_tool_logs for all using(true) with check(true); exception when duplicate_object then null; end $$;
insert into public.f2_products(product_name) values('KMG'),('KMX'),('KRF') on conflict(product_name) do nothing;
insert into public.f2_items(product_id,part_no) select id,'443' from public.f2_products where product_name='KMG' on conflict(product_id,part_no) do nothing;
insert into public.f2_tools(machine_no,t_no,tool_name,current_machine_no) select 1,n,null,1 from generate_series(1,80)n on conflict(machine_no,t_no) do nothing;
